python3 -c '
import gzip, glob
COMP = str.maketrans("ACGTN", "TGCAN")
def revcomp(s): return s.translate(COMP)[::-1]
SCAFFOLD = "GTTTTAGAGCTA"

def get_spacer(read):
    k = read.find(SCAFFOLD)
    if k >= 20:
        return read[k-20:k]
    rc = revcomp(read)
    k = rc.find(SCAFFOLD)
    if k >= 20:
        return rc[k-20:k]
    return None

for p in ["part_A", "part_B", "part_C"]:
    lib = set()
    for line in open(f"/task/input/{p}/library.tsv"):
        lib.add(line.split("\t")[1])
    for fq in sorted(glob.glob(f"/task/input/{p}/fastq/*.fastq.gz")):
        tot, match = 0, 0
        with gzip.open(fq, "rt") as f:
            for i, line in enumerate(f):
                if i % 4 == 1:
                    tot += 1
                    sp = get_spacer(line.rstrip())
                    if sp in lib:
                        match += 1
        print(p, fq.split("/")[-1], "total:", tot, "matched:", match, f"{match/tot*100:.1f}%")
'

