import pandas as pd
res = pd.read_csv("/tmp/mageck_part_A.gene_summary.txt", sep="\t")
ref = pd.read_csv("/task/input/part_A/reference_genes.tsv", sep="\t")
ref_map = dict(zip(ref["gene"], ref["expected_class"]))
res_map = {}
for _, r in res.iterrows():
    g = r["id"]
    if r["neg|fdr"] <= 0.05:
        res_map[g] = "sensitiser"
    elif r["pos|fdr"] <= 0.05:
        res_map[g] = "resistance"
    else:
        res_map[g] = "none"

mod_ok, mod_tot, none_fp, none_tot = 0, 0, 0, 0
for g, exp in ref_map.items():
    got = res_map.get(g, "none")
    if exp != "none":
        mod_tot += 1
        if got == exp: mod_ok += 1
        else: print(f"MISSED {g}: exp {exp}, got {got}")
    else:
        none_tot += 1
        if got != "none":
            none_fp += 1
            print(f"FP NONE {g}: got {got}")
